<?php require dirname(__DIR__).'/includes/app.php'; $admins=read_json('admins.json',[]); if($admins){header('Location: /admin/');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$user=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');if(strlen($user)<3||strlen($pass)<12){$error='Use a username of at least 3 characters and a password of at least 12 characters.';}else{write_json('admins.json',[['username'=>$user,'password'=>password_hash($pass,PASSWORD_DEFAULT)]]);header('Location: /admin/');exit;}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Setup</title><link rel="stylesheet" href="/admin/admin.css"></head><body class="login-body"><form class="login-card" method="post"><div class="admin-logo">GB</div><h1>Create Admin</h1><p>First-time setup for Galindos Builders LLC.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username<input name="username" required autocomplete="username"></label><label>Password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><button>Create Administrator</button></form></body></html>